// Host-bound Kepler orbits. Display distance and time are intentionally scaled.
const planetDays=[0,87.969,224.701,365.256,686.98,4332.59,10759.22,30685.4,60189];
const cross=(a,b)=>({x:a.y*b.z-a.z*b.y,y:a.z*b.x-a.x*b.z,z:a.x*b.y-a.y*b.x}),unit=a=>{const r=Math.hypot(a.x,a.y,a.z)||1;return {x:a.x/r,y:a.y/r,z:a.z/r};};
export class SatelliteSystem {
 constructor(data,simulation,settings={}){this.time=0;this.histories=new Map();this.owner=simulation;this.frames=globalThis.ShiyuThreeBodyPhysics;const alpha=simulation.bodies[0];this.hostRadii=simulation.bodies.map(h=>Math.hypot(h.x-alpha.x,h.y-alpha.y,h.z-alpha.z));this.settings=settings;const visible=data.filter(m=>m.radiusKm>=200||m.parent===4),ranges={};for(const m of visible){const r=ranges[m.parent]||[Infinity,0];r[0]=Math.min(r[0],m.a);r[1]=Math.max(r[1],m.a);ranges[m.parent]=r;}this.items=data.filter(m=>m.radiusKm>=200||m.parent===4).map(m=>({...m,major:true,relativeA:ranges[m.parent][0]===ranges[m.parent][1]?.5:Math.log(m.a/ranges[m.parent][0])/Math.log(ranges[m.parent][1]/ranges[m.parent][0]),phase:(settings[m.id]?.angle??m.mean)*Math.PI/180,periodDisplay:this.orbitalPeriod(simulation,m.parent)/(2+6*(1-Math.exp(-Math.log1p(planetDays[m.parent]/m.period)/6))),x:0,y:0,z:0}));this.advance(simulation,0);}
 parameters(id){const m=this.items.find(m=>m.id===id),s=this.settings[id]||{};return {inclination:m.inc,angle:m.mean,speed:1,radius:1,...s};}
 set(id,key,value){const limits={inclination:[0,180],angle:[0,360],speed:[.1,10],radius:[.6,2]};if(!limits[key]||!Number.isFinite(value))return;this.settings[id]={...this.settings[id],[key]:Math.max(limits[key][0],Math.min(limits[key][1],value))};if(key==='angle')this.items.find(m=>m.id===id).phase=value*Math.PI/180;}
 orbitalPeriod(simulation,parent){const h=simulation.bodies[parent],a=simulation.bodies[0],r=Math.hypot(h.x-a.x,h.y-a.y,h.z-a.z);return Math.PI*2*Math.sqrt(r*r*r/(simulation.gravity*(a.mass+h.mass)));}
 advance(simulation,duration){this.time+=duration;for(const m of this.items){const s=this.parameters(m.id);m.phase=(m.phase+duration*s.speed*Math.PI*2/m.periodDisplay)%(Math.PI*2);Object.assign(m,this.position(m,m.phase));}}
 position(m,phase){const s=this.parameters(m.id);let E=phase;for(let k=0;k<10;k++)E-=(E-m.e*Math.sin(E)-phase)/(1-m.e*Math.cos(E));const x=Math.cos(E)-m.e,y=Math.sqrt(1-m.e*m.e)*Math.sin(E),w=m.peri*Math.PI/180,n=m.node*Math.PI/180,inc=s.inclination*Math.PI/180,u=x*Math.cos(w)-y*Math.sin(w),v=x*Math.sin(w)+y*Math.cos(w),px=u*Math.cos(n)-v*Math.cos(inc)*Math.sin(n),py=u*Math.sin(n)+v*Math.cos(inc)*Math.cos(n),pz=v*Math.sin(inc);if(m.frame==='ecliptic')return {x:px,y:py,z:pz};const normal=m.frame==='Laplace'?this.frames.equatorialPole(m.poleRA,m.poleDec):this.frames.spinBasis(m.parent).axis,ex=unit(cross(this.frames.equatorialPole(0,90),normal)),ey=cross(normal,ex);return {x:ex.x*px+ey.x*py+normal.x*pz,y:ex.y*px+ey.y*py+normal.y*pz,z:ex.z*px+ey.z*py+normal.z*pz};}

 display(simulation,scale){const zoom=Math.max(1,scale);return this.items.flatMap(m=>{const host=simulation.bodies[m.parent],bodyRadius=7+Math.cbrt(this.frames.multiMasses[m.parent])*5,s=this.parameters(m.id),gap=Math.min(...this.hostRadii.slice(1).filter((_,i)=>i+1!==m.parent).map(r=>Math.abs(r-this.hostRadii[m.parent]))),budget=gap*.43*zoom,size=Math.max(.6,Math.min(bodyRadius*.45,Math.max(1.2,(budget-bodyRadius-2)/3))*m.radiusKm/Math.max(...this.items.filter(x=>x.parent===m.parent).map(x=>x.radiusKm))),inner=bodyRadius+size+2,minimum=Math.max(.02,1-m.e),maximum=1+m.e,available=(budget-size)/maximum,desired=inner/minimum+Math.max(0,available-inner/minimum)*Math.min(1,m.relativeA*s.radius),factor=Math.max(inner/minimum,Math.min(desired,available))/zoom;return [{...m,orbitFactor:factor,x:host.x+m.x*factor,y:host.y+m.y*factor,z:host.z+m.z*factor,size,relativeRadius:Math.hypot(m.x,m.y,m.z)}];});}

 orbit(moon,simulation){const h=simulation.bodies[moon.parent];return Array.from({length:65},(_,i)=>{const p=this.position(moon,i*Math.PI*2/64);return {x:h.x+p.x*moon.orbitFactor,y:h.y+p.y*moon.orbitFactor,z:h.z+p.z*moon.orbitFactor};});}
 trail(moon,record){const duration=Math.min(.8,Math.max(.2,moon.periodDisplay*.3)),history=this.histories.get(moon.id)||[];if(record&&(!history.length||this.time-history.at(-1).t>=.006)){history.push({x:moon.x,y:moon.y,z:moon.z,t:this.time});this.histories.set(moon.id,history);}while(history.length&&(this.time-history[0].t>duration||history.length>150))history.shift();return {points:history,duration};}
 snapshot(){return this.items.map(m=>({id:m.id,name:m.name,parent:m.parent,massRatio:m.massRatio,mass:m.massRatio===null?null:this.ownerMass(m),x:m.x,y:m.y,z:m.z,relativeRadius:Math.hypot(m.x,m.y,m.z)}));}
 ownerMass(m){return this.owner.bodies[m.parent].mass*m.massRatio;}
}
